import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Archive, ArrowLeft, ArrowRight, Bot, ChevronDown, ChevronUp, CircleUserRound, Clock3, Copy, Expand, FileText, FileUp, Images, Inbox, Instagram, Link, Linkedin, MailOpen, MessageCircle, MoreHorizontal, Pencil, Pin, RefreshCw, Search, Trash2, UserRound, UserRoundCheck, X } from "lucide-react";
import { conversationMediaUrl, conversationsAPI, type CommunicationMessage, type Conversation, type ConversationActivity, type ConversationDetail, type ConversationLabel, type SharedConversationItem } from "@/api/conversations";
import { commercialEntitiesAPI, type UserOption } from "@/services/commercial-entities";
import { useAuth } from "@/contexts/AuthContext";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { ChatMessage, useAuthenticatedMediaUrl } from "@/components/commercial/ChatMessage";
import { MessageComposer } from "@/components/commercial/MessageComposer";
import { getChannelCapabilities } from "@/lib/channel-capabilities";

type Channel = "whatsapp" | "instagram" | "linkedin";
type Filter = "all" | "unread" | "mine" | "ai" | "human" | "archived";

const channels: Record<Channel, { label: string; icon: typeof MessageCircle; className: string; connected: boolean }> = {
  whatsapp: { label: "WhatsApp", icon: MessageCircle, className: "text-emerald-500", connected: true },
  instagram: { label: "Instagram", icon: Instagram, className: "text-pink-500", connected: false },
  linkedin: { label: "LinkedIn", icon: Linkedin, className: "text-sky-500", connected: false },
};

function ChannelBadge({ channel = "whatsapp" as Channel }: { channel?: string }) {
  const config = channels[channel as Channel] || channels.whatsapp;
  const Icon = config.icon;
  return <span className={cn("inline-flex items-center gap-1 text-[11px] font-medium", config.className)}><Icon className="h-3.5 w-3.5" />{config.label}</span>;
}

function initials(name?: string | null) {
  return (name || "Contato").split(" ").filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toUpperCase() || "C";
}
function conversationName(conversation: Conversation) { return conversation.display_name || conversation.lead_name || conversation.lead_phone || (conversation.conversation_type === "group" ? "Grupo do WhatsApp" : "Contato sem nome"); }
function ConversationAvatar({ conversation, className }: { conversation: Conversation; className?: string }) { const name = conversationName(conversation); return <Avatar className={className}>{conversation.profile_picture_url ? <AvatarImage src={conversation.profile_picture_url} alt={name} referrerPolicy="no-referrer" /> : null}<AvatarFallback>{initials(name)}</AvatarFallback></Avatar>; }

function formatTime(value?: string | null) {
  if (!value) return "";
  return new Intl.DateTimeFormat("pt-BR", { hour: "2-digit", minute: "2-digit" }).format(new Date(value));
}

function sameDay(left?: string | null, right?: string | null) { return Boolean(left && right && new Date(left).toDateString() === new Date(right).toDateString()); }
function dayLabel(value: string) { const date = new Date(value); const today = new Date(); const yesterday = new Date(today); yesterday.setDate(today.getDate() - 1); if (date.toDateString() === today.toDateString()) return "Hoje"; if (date.toDateString() === yesterday.toDateString()) return "Ontem"; return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric" }).format(date); }
function listDate(value?: string | null) { if (!value) return ""; const date = new Date(value); const today = new Date(); const yesterday = new Date(today); yesterday.setDate(today.getDate() - 1); if (date.toDateString() === today.toDateString()) return formatTime(value); if (date.toDateString() === yesterday.toDateString()) return "Ontem"; const days = Math.floor((today.getTime() - date.getTime()) / 86400000); if (days < 7) return new Intl.DateTimeFormat("pt-BR", { weekday: "short" }).format(date).replace(".", ""); return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "2-digit" }).format(date); }
function droppedFileType(file: File): "image" | "audio" | "video" | "document" | null { if (file.type.startsWith("image/")) return "image"; if (file.type.startsWith("audio/")) return "audio"; if (file.type.startsWith("video/")) return "video"; if (["application/pdf", "text/plain", "application/zip", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/vnd.ms-excel", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/vnd.ms-powerpoint", "application/vnd.openxmlformats-officedocument.presentationml.presentation"].includes(file.type)) return "document"; return null; }

function formatDate(value?: string | null) {
  if (!value) return "";
  const date = new Date(value);
  const today = new Date();
  const yesterday = new Date(); yesterday.setDate(today.getDate() - 1);
  if (date.toDateString() === today.toDateString()) return `Hoje, ${formatTime(value)}`;
  if (date.toDateString() === yesterday.toDateString()) return `Ontem, ${formatTime(value)}`;
  return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(date);
}

function modeLabel(mode?: string) {
  if (mode === "ai") return "IA atendendo";
  return "Atendimento humano";
}

function statusLabel(status?: string) {
  return ({ open: "Aberta", waiting: "Aguardando", resolved: "Encerrada", closed: "Encerrada" } as Record<string, string>)[status || ""] || "Aberta";
}

export function ChatsPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [detail, setDetail] = useState<ConversationDetail | null>(null);
  const [messages, setMessages] = useState<CommunicationMessage[]>([]);
  const [activities, setActivities] = useState<ConversationActivity[]>([]);
  const [users, setUsers] = useState<UserOption[]>([]);
  const [availableLabels, setAvailableLabels] = useState<ConversationLabel[]>([]);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [loading, setLoading] = useState(true);
  const [loadingMessages, setLoadingMessages] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<"profile" | "activities">("profile");
  const [reply, setReply] = useState<CommunicationMessage | null>(null);
  const [lightbox, setLightbox] = useState<string | null>(null);
  const [hasMoreMessages, setHasMoreMessages] = useState(false);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const [conversationSearch, setConversationSearch] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchResults, setSearchResults] = useState<CommunicationMessage[]>([]);
  const [searchIndex, setSearchIndex] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [pendingFiles, setPendingFiles] = useState<File[]>([]);
  const [pendingCaption, setPendingCaption] = useState("");
  const [sharedType, setSharedType] = useState<"media" | "documents" | "links" | null>(null);
  const [sharedItems, setSharedItems] = useState<SharedConversationItem[]>([]);
  const [participants, setParticipants] = useState<Array<{ name: string | null; phone?: string | null; profilePictureUrl?: string | null; role: string }>>([]);
  const messagesRef = useRef<HTMLDivElement | null>(null);
  const searchTimer = useRef<number | undefined>(undefined);
  const scrollRequest = useRef<"initial" | "bottom" | null>(null);
  const initialBottomAnchor = useRef(false);
  const programmaticScroll = useRef(false);
  const prependingMessages = useRef(false);
  const newMessageCount = useRef(0);
  const previousLastMessageId = useRef<number | null>(null);
  const isNearBottom = (element: HTMLDivElement) => element.scrollHeight - element.scrollTop - element.clientHeight <= 160;
  const scrollToBottom = (behavior: ScrollBehavior = "auto") => { const element = messagesRef.current; if (!element) return; programmaticScroll.current = true; element.scrollTo({ top: element.scrollHeight, behavior }); requestAnimationFrame(() => { programmaticScroll.current = false; }); };

  const loadConversations = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const result = await conversationsAPI.list({ search: search.trim() || undefined, filter, assignedUserId: filter === "mine" ? Number(user?.id) : undefined });
      setConversations(result.conversations);
      setSelectedId((current) => current && result.conversations.some((item) => item.id === current) ? current : result.conversations[0]?.id || null);
      setError(null);
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível carregar as conversas."); }
    finally { if (!silent) setLoading(false); }
  }, [filter, search, user?.id]);

  const loadSelected = useCallback(async (id: number, silent = false) => {
    if (!silent) setLoadingMessages(true);
    try {
      const [nextDetail, nextMessages, nextActivities] = await Promise.all([conversationsAPI.detail(id), conversationsAPI.messages(id), conversationsAPI.activities(id)]);
      const latestId = nextMessages.messages.at(-1)?.id || null;
      const wasNearBottom = !silent || !messagesRef.current || isNearBottom(messagesRef.current);
      if (!silent || previousLastMessageId.current === null) { scrollRequest.current = "initial"; initialBottomAnchor.current = true; }
      else if (latestId !== previousLastMessageId.current && wasNearBottom) scrollRequest.current = "bottom";
      else if (latestId !== previousLastMessageId.current) newMessageCount.current += 1;
      previousLastMessageId.current = latestId;
      setDetail(nextDetail); setMessages(nextMessages.messages); setHasMoreMessages(Boolean(nextMessages.hasMore)); setActivities(nextActivities.activities);
      if (nextDetail.unread_count > 0) { await conversationsAPI.markRead(id); setConversations((current) => current.map((item) => item.id === id ? { ...item, unread_count: 0 } : item)); }
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível carregar a conversa."); }
    finally { if (!silent) setLoadingMessages(false); }
  }, []);

  useLayoutEffect(() => { if (!scrollRequest.current || !messages.length) return; const request = scrollRequest.current; scrollRequest.current = null; requestAnimationFrame(() => scrollToBottom(request === "bottom" ? "smooth" : "auto")); }, [messages.length, selectedId]);
  useEffect(() => {
    const element = messagesRef.current;
    if (!element || !selectedId) return;
    const observer = new ResizeObserver(() => { if (initialBottomAnchor.current && !prependingMessages.current) scrollToBottom(); });
    observer.observe(element);
    const handleUserScroll = () => { if (!programmaticScroll.current && element.scrollHeight - element.scrollTop - element.clientHeight > 160) initialBottomAnchor.current = false; };
    element.addEventListener("scroll", handleUserScroll, { passive: true });
    return () => { observer.disconnect(); element.removeEventListener("scroll", handleUserScroll); };
  }, [selectedId, messages.length]);

  useEffect(() => { void loadConversations(); }, [loadConversations]);
  useEffect(() => { void Promise.all([commercialEntitiesAPI.getUsers(), commercialEntitiesAPI.getLabels()]).then(([userResult, labelResult]) => { setUsers(userResult.users); setAvailableLabels(labelResult.labels); }).catch(() => { setUsers([]); setAvailableLabels([]); }); }, []);
  useEffect(() => { if (selectedId) void loadSelected(selectedId); else { setDetail(null); setMessages([]); setActivities([]); } }, [loadSelected, selectedId]);
  useEffect(() => { if (!detail) return; void conversationsAPI.refreshProfile(detail.id).then((profile) => { if (profile.unavailable) return; setDetail((current) => current?.id === detail.id ? { ...current, profile_picture_url: profile.profilePictureUrl, display_name: profile.displayName || current.display_name, participant_count: profile.participantCount, profile_picture_stale: false } : current); setConversations((current) => current.map((item) => item.id === detail.id ? { ...item, profile_picture_url: profile.profilePictureUrl, display_name: profile.displayName || item.display_name, participant_count: profile.participantCount, profile_picture_stale: false } : item)); if (profile.participants) setParticipants(profile.participants); }).catch(() => {}); }, [detail?.id]);
  useEffect(() => {
    window.clearTimeout(searchTimer.current);
    searchTimer.current = window.setTimeout(() => void loadConversations(), 250);
    return () => window.clearTimeout(searchTimer.current);
  }, [loadConversations]);
  useEffect(() => { const timer = window.setInterval(() => { void loadConversations(true); if (selectedId) void loadSelected(selectedId, true); }, 12000); return () => window.clearInterval(timer); }, [loadConversations, loadSelected, selectedId]);

  const selected = useMemo(() => conversations.find((item) => item.id === selectedId) || null, [conversations, selectedId]);
  const capabilities = useMemo(() => getChannelCapabilities(detail?.channel || selected?.channel || "whatsapp"), [detail?.channel, selected?.channel]);
  const refreshProfile = async () => { if (!detail) return; try { const profile = await conversationsAPI.refreshProfile(detail.id, true); if (profile.unavailable) throw new Error("Informações do WhatsApp indisponíveis no momento."); setDetail((current) => current ? { ...current, profile_picture_url: profile.profilePictureUrl, display_name: profile.displayName || current.display_name, participant_count: profile.participantCount, profile_picture_stale: false } : current); setParticipants(profile.participants || []); await loadConversations(true); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível atualizar as informações do WhatsApp."); } };
  const changeHandling = async () => {
    if (!detail) return;
    if (detail.handling_mode !== "ai" && !detail.ai_agent_id) { setError("Nenhum agente de IA configurado."); return; }
    const next = detail.handling_mode === "ai" ? "human" : "ai";
    try { await conversationsAPI.setHandling(detail.id, next); await loadSelected(detail.id, true); await loadConversations(true); }
    catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível alterar o atendimento."); }
  };
  const assign = async (value: string) => { if (!detail) return; try { await conversationsAPI.assign(detail.id, value === "unassigned" ? null : Number(value)); await loadSelected(detail.id, true); await loadConversations(true); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível atribuir a conversa."); } };
  const send = async (message: string, quotedMessageId?: number | null) => { if (!detail) return; setSending(true); try { scrollRequest.current = "bottom"; await conversationsAPI.send(detail.id, message, quotedMessageId); await loadSelected(detail.id, true); await loadConversations(true); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível enviar a mensagem."); } finally { setSending(false); } };
  const sendMedia = async (file: File | Blob, type: "image" | "audio" | "video" | "document", caption?: string, filename?: string, quotedMessageId?: number | null) => { if (!detail) return; setSending(true); try { scrollRequest.current = "bottom"; await conversationsAPI.sendMedia(detail.id, file, type, caption, filename, quotedMessageId); await loadSelected(detail.id, true); await loadConversations(true); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível enviar a mídia."); } finally { setSending(false); } };
  const copyMessage = async (message: CommunicationMessage) => { if (message.body_text) await navigator.clipboard?.writeText(message.body_text); };
  const loadOlderMessages = async () => { if (!detail || loadingOlder || !hasMoreMessages || !messages.length || !messagesRef.current) return; const container = messagesRef.current; const previousHeight = container.scrollHeight; prependingMessages.current = true; initialBottomAnchor.current = false; setLoadingOlder(true); try { const result = await conversationsAPI.messages(detail.id, messages[0].id); setMessages((current) => [...result.messages, ...current]); setHasMoreMessages(Boolean(result.hasMore)); requestAnimationFrame(() => { if (messagesRef.current) messagesRef.current.scrollTop = messagesRef.current.scrollHeight - previousHeight; prependingMessages.current = false; }); } catch (requestError) { prependingMessages.current = false; setError(requestError instanceof Error ? requestError.message : "Não foi possível carregar o histórico."); } finally { setLoadingOlder(false); } };
  const copyPhone = async () => { if (detail?.lead_phone) await navigator.clipboard?.writeText(detail.lead_phone); };
  const runConversationSearch = async () => { if (!detail || conversationSearch.trim().length < 2) return; try { const result = await conversationsAPI.searchMessages(detail.id, conversationSearch.trim()); setSearchResults(result.messages); setSearchIndex(0); setMessages((current) => [...current, ...result.messages.filter((resultMessage) => !current.some((item) => item.id === resultMessage.id))].sort((left, right) => left.id - right.id)); const first = result.messages[0]; if (first) requestAnimationFrame(() => document.getElementById(`message-${first.id}`)?.scrollIntoView({ behavior: "smooth", block: "center" })); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível pesquisar nesta conversa."); } };
  const moveSearch = (direction: number) => { if (!searchResults.length) return; const next = (searchIndex + direction + searchResults.length) % searchResults.length; setSearchIndex(next); document.getElementById(`message-${searchResults[next].id}`)?.scrollIntoView({ behavior: "smooth", block: "center" }); };
  const acceptFiles = (files: File[]) => { const valid = files.filter((file) => droppedFileType(file)); if (valid.length !== files.length) setError("Um ou mais arquivos não possuem formato suportado."); if (valid.length) setPendingFiles(valid); };
  const sendPendingFiles = async () => { if (!detail || !pendingFiles.length) return; setSending(true); try { for (const file of pendingFiles) { const type = droppedFileType(file); if (type) await conversationsAPI.sendMedia(detail.id, file, type, pendingCaption || undefined, file.name, reply?.id); } setPendingFiles([]); setPendingCaption(""); setReply(null); await loadSelected(detail.id, true); await loadConversations(true); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível enviar os arquivos."); } finally { setSending(false); } };
  const updateBudget = async (budget: string | null) => { if (!detail?.lead_id) return; await conversationsAPI.updateLeadBudget(detail.lead_id, budget); await loadSelected(detail.id, true); };
  const updateLabels = async (ids: number[]) => { if (!detail?.lead_id) return; await commercialEntitiesAPI.setLeadLabels(String(detail.lead_id), ids.map(String)); await loadSelected(detail.id, true); };
  const openShared = async (type: "media" | "documents" | "links") => { if (!detail) return; setSharedType(type); try { const result = await conversationsAPI.shared(detail.id, type); setSharedItems(result.items); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível carregar os conteúdos compartilhados."); } };
  const toggleConversation = async (action: "pin" | "archive" | "unread" | "delete") => { if (!detail) return; try { if (action === "pin") await conversationsAPI.setPinned(detail.id, !detail.pinned_at); if (action === "archive") await conversationsAPI.setArchived(detail.id, !detail.archived_at); if (action === "unread") await conversationsAPI.markUnread(detail.id); if (action === "delete") { if (!window.confirm("Excluir conversa? A conversa será ocultada do Chats, preservando o histórico.")) return; await conversationsAPI.hide(detail.id); } await loadConversations(true); if (action === "archive" || action === "delete") { setSelectedId(null); setDetail(null); } else await loadSelected(detail.id, true); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : "Não foi possível atualizar a conversa."); } };

  return <TooltipProvider>
    <main className="flex h-[calc(100vh-5.5rem)] min-h-[620px] flex-col overflow-hidden p-3 md:p-5">
      <div className="mb-3 flex shrink-0 items-center justify-between gap-3"><div><p className="text-xs font-medium uppercase tracking-[0.18em] text-primary">Comercial</p><h1 className="text-2xl font-semibold tracking-tight">Chats</h1></div><div className="flex items-center gap-2"><Badge variant="outline" className="hidden gap-1.5 sm:inline-flex"><MessageCircle className="h-3.5 w-3.5 text-emerald-500" />WhatsApp conectado</Badge><Button variant="outline" size="icon" onClick={() => void loadConversations()} aria-label="Atualizar conversas" title="Atualizar conversas"><RefreshCw className="h-4 w-4" /></Button></div></div>
      {error ? <div className="mb-3 flex items-center justify-between rounded-md border border-destructive/40 bg-destructive/5 px-3 py-2 text-sm text-destructive"><span>{error}</span><Button variant="ghost" size="sm" onClick={() => { setError(null); void loadConversations(); }}>Tentar novamente</Button></div> : null}
      {detail ? <div className="mb-2 flex items-center justify-end gap-1"><Button variant="ghost" size="icon" onClick={() => void toggleConversation("pin")} title={detail.pinned_at ? "Desafixar conversa" : "Fixar conversa"} aria-label={detail.pinned_at ? "Desafixar conversa" : "Fixar conversa"}><Pin className={cn("h-4 w-4", detail.pinned_at && "fill-current text-primary")} /></Button><Button variant="ghost" size="icon" onClick={() => void toggleConversation("archive")} title={detail.archived_at ? "Desarquivar conversa" : "Arquivar conversa"} aria-label={detail.archived_at ? "Desarquivar conversa" : "Arquivar conversa"}><Archive className="h-4 w-4" /></Button><Button variant="ghost" size="icon" onClick={() => void toggleConversation("unread")} title="Marcar como não lida" aria-label="Marcar como não lida"><MailOpen className="h-4 w-4" /></Button><Button variant="ghost" size="icon" onClick={() => void toggleConversation("delete")} title="Excluir conversa" aria-label="Excluir conversa"><Trash2 className="h-4 w-4" /></Button></div> : null}
      <div className="grid min-h-0 flex-1 overflow-hidden rounded-lg border bg-card shadow-sm lg:grid-cols-[300px_minmax(0,1fr)_320px]">
        <aside className="flex min-h-0 flex-col border-b lg:border-b-0 lg:border-r"><div className="border-b p-3"><div className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><Input className="h-9 pl-9" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar conversa, lead ou telefone..." /></div><div className="mt-3 flex flex-wrap gap-1"><FilterButton active={filter === "all"} onClick={() => setFilter("all")}>Todos</FilterButton><FilterButton active={filter === "unread"} onClick={() => setFilter("unread")}>Não lidos</FilterButton><FilterButton active={filter === "mine"} onClick={() => setFilter("mine")}>Minhas</FilterButton><FilterButton active={filter === "ai"} onClick={() => setFilter("ai")}>IA</FilterButton><FilterButton active={filter === "human"} onClick={() => setFilter("human")}>Humano</FilterButton></div></div><div className="min-h-0 flex-1 overflow-y-auto">{loading ? <div className="space-y-2 p-3"><Skeleton className="h-16 w-full" /><Skeleton className="h-16 w-full" /><Skeleton className="h-16 w-full" /></div> : conversations.length === 0 ? <EmptyState icon={Inbox} title={search ? "Nenhuma conversa encontrada" : "Suas conversas aparecerão aqui"} /> : conversations.map((conversation) => <ConversationItem key={conversation.id} conversation={conversation} selected={conversation.id === selectedId} onClick={() => setSelectedId(conversation.id)} />)}</div></aside>
        <section onDragEnter={(event) => { event.preventDefault(); setDragging(true); }} onDragOver={(event) => event.preventDefault()} onDragLeave={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node)) setDragging(false); }} onDrop={(event) => { event.preventDefault(); setDragging(false); acceptFiles(Array.from(event.dataTransfer.files)); }} onPaste={(event) => { const files = Array.from(event.clipboardData.files); if (files.length) { event.preventDefault(); acceptFiles(files); } }} className="relative flex min-h-0 flex-col border-b lg:border-b-0 lg:border-r">{detail ? <><header className="flex shrink-0 items-center justify-between gap-3 border-b px-4 py-3"><div className="flex min-w-0 items-center gap-3"><ConversationAvatar conversation={detail} className="h-10 w-10" /><div className="min-w-0"><h2 className="truncate font-semibold">{conversationName(detail)}</h2><div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground"><ChannelBadge channel={detail.channel} /><span>•</span><span>{detail.conversation_type === "group" ? `${detail.participant_count || 0} participantes` : detail.lead_phone || "Sem telefone"}</span></div></div></div><div className="flex items-center gap-1"><Button variant="ghost" size="icon" onClick={() => setSearchOpen((value) => !value)} title="Pesquisar mensagens" aria-label="Pesquisar mensagens"><Search className="h-4 w-4" /></Button><Badge variant="outline" className={cn(detail.handling_mode === "ai" ? "border-sky-500/40 text-sky-600" : "border-primary/40 text-primary")}><span className="mr-1.5 h-1.5 w-1.5 rounded-full bg-current" />{modeLabel(detail.handling_mode)}</Badge><Button variant="ghost" size="icon" onClick={changeHandling} title={detail.handling_mode === "ai" ? "Assumir atendimento" : detail.ai_agent_id ? "Devolver para IA" : "Nenhum agente de IA configurado"} aria-label="Alterar modo de atendimento" disabled={detail.handling_mode !== "ai" && !detail.ai_agent_id}><UserRoundCheck className="h-4 w-4" /></Button></div></header>{searchOpen ? <div className="flex items-center gap-2 border-b bg-muted/20 p-2"><Input autoFocus value={conversationSearch} onChange={(event) => setConversationSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") void runConversationSearch(); if (event.key === "Escape") setSearchOpen(false); }} placeholder="Pesquisar nesta conversa" className="h-8" /><span className="whitespace-nowrap text-xs text-muted-foreground">{searchResults.length ? `${searchIndex + 1} de ${searchResults.length}` : "0 resultados"}</span><Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => moveSearch(-1)} disabled={!searchResults.length}><ChevronUp className="h-4 w-4" /></Button><Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => moveSearch(1)} disabled={!searchResults.length}><ChevronDown className="h-4 w-4" /></Button><Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => { setSearchOpen(false); setSearchResults([]); }}><X className="h-4 w-4" /></Button></div> : null}<div ref={messagesRef} onScroll={(event) => { if (event.currentTarget.scrollTop < 80) void loadOlderMessages(); }} className="min-h-0 flex-1 overflow-y-auto bg-muted/20 px-4 py-5">{loadingOlder ? <div className="pb-3 text-center text-xs text-muted-foreground">Carregando histórico...</div> : null}{loadingMessages ? <div className="space-y-3"><Skeleton className="h-12 w-2/3" /><Skeleton className="ml-auto h-16 w-1/2" /><Skeleton className="h-10 w-1/3" /></div> : messages.length === 0 ? <EmptyState icon={MessageCircle} title="Nenhuma mensagem nesta conversa" /> : <div className="mx-auto flex max-w-3xl flex-col gap-2">{messages.map((message, index) => <div key={message.id}>{!sameDay(message.created_at, messages[index - 1]?.created_at) ? <div className="my-3 flex justify-center"><span className="rounded-md border bg-background/90 px-3 py-1 text-[11px] text-muted-foreground shadow-sm">{dayLabel(message.created_at)}</span></div> : null}<ChatMessage message={message} conversationId={detail.id} isGroup={detail.conversation_type === "group"} capabilities={capabilities} quoted={message.quoted_message_id ? messages.find((item) => item.id === message.quoted_message_id) : null} onReply={setReply} onCopy={copyMessage} onOpenMedia={setLightbox} /></div>)}</div>}</div><MessageComposer onSendText={send} onSendMedia={sendMedia} sending={sending} reply={reply} onClearReply={() => setReply(null)} onError={setError} />{dragging ? <div className="absolute inset-3 z-30 flex items-center justify-center rounded-md border-2 border-dashed border-primary bg-background/90"><div className="text-center"><FileUp className="mx-auto mb-2 h-8 w-8 text-primary" /><p className="font-medium">Solte os arquivos para enviar</p></div></div> : null}</> : <EmptyState icon={MessageCircle} title="Selecione uma conversa para começar" />}</section>
        <aside className="flex min-h-0 flex-col overflow-y-auto bg-background"><div className="flex shrink-0 border-b">{(["profile", "activities"] as const).map((tab) => <button key={tab} className={cn("flex-1 border-b-2 px-3 py-3 text-sm font-medium", activeTab === tab ? "border-primary text-foreground" : "border-transparent text-muted-foreground")} onClick={() => setActiveTab(tab)}>{tab === "profile" ? "Perfil" : "Atividades"}</button>)}</div>{detail ? activeTab === "profile" ? detail.conversation_type === "group" ? <GroupProfilePanel detail={detail} participants={participants} onRefresh={refreshProfile} onShared={openShared} /> : <ProfilePanel detail={detail} users={users} availableLabels={availableLabels} onAssign={assign} onCopyPhone={copyPhone} onOpenLead={() => navigate(`/comercial/leads/${(detail.lead_name || "lead").toLowerCase().replace(/\s+/g, "-")}-${detail.lead_id || ""}`)} onBudget={updateBudget} onLabels={updateLabels} onShared={openShared} /> : <ActivityPanel activities={activities} /> : <EmptyState icon={CircleUserRound} title="O contexto do lead aparecerá aqui" />}</aside>
      </div>
      {lightbox ? <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4" role="dialog" aria-modal="true" onClick={() => setLightbox(null)} onKeyDown={(event) => { if (event.key === "Escape") setLightbox(null); }} tabIndex={-1}><Button variant="ghost" size="icon" className="absolute right-4 top-4 text-white" onClick={() => setLightbox(null)} aria-label="Fechar imagem"><X className="h-5 w-5" /></Button><img src={lightbox} alt="Visualização ampliada" className="max-h-[90vh] max-w-[95vw] object-contain" onClick={(event) => event.stopPropagation()} /></div> : null}
      {pendingFiles.length ? <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-lg rounded-md border bg-card p-4 shadow-xl"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Enviar arquivos</h2><p className="text-xs text-muted-foreground">{pendingFiles.length} arquivo(s), enviados em sequência</p></div><Button variant="ghost" size="icon" onClick={() => setPendingFiles([])}><X className="h-4 w-4" /></Button></div><div className="my-4 max-h-64 space-y-2 overflow-y-auto">{pendingFiles.map((file, index) => <div key={`${file.name}-${index}`} className="flex items-center gap-3 rounded-md border p-2"><FileUp className="h-5 w-5 text-primary" /><div className="min-w-0 flex-1"><p className="truncate text-sm">{file.name}</p><p className="text-xs text-muted-foreground">{file.type || "Arquivo"} · {(file.size / 1024 / 1024).toFixed(1)} MB</p></div><Button variant="ghost" size="icon" onClick={() => setPendingFiles((items) => items.filter((_, itemIndex) => itemIndex !== index))}><X className="h-4 w-4" /></Button></div>)}</div><Input value={pendingCaption} onChange={(event) => setPendingCaption(event.target.value)} placeholder="Legenda opcional" /><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={() => setPendingFiles([])}>Cancelar</Button><Button onClick={() => void sendPendingFiles()} disabled={sending}>{sending ? "Enviando..." : "Enviar"}</Button></div></div></div> : null}
      {sharedType && detail ? <SharedContentDialog conversationId={detail.id} type={sharedType} items={sharedItems} onClose={() => { setSharedType(null); setSharedItems([]); }} /> : null}
    </main>
  </TooltipProvider>;
}

function FilterButton({ active, children, onClick }: { active: boolean; children: string; onClick: () => void }) { return <button className={cn("rounded-full border px-2.5 py-1 text-xs transition-colors", active ? "border-primary bg-primary/10 text-primary" : "border-transparent text-muted-foreground hover:border-border hover:text-foreground")} onClick={onClick}>{children}</button>; }
function EmptyState({ icon: Icon, title }: { icon: typeof Inbox; title: string }) { return <div className="flex h-full min-h-32 flex-col items-center justify-center gap-2 px-6 py-10 text-center text-muted-foreground"><Icon className="h-7 w-7 opacity-50" /><p className="text-sm">{title}</p></div>; }
function ConversationItem({ conversation, selected, onClick }: { conversation: Conversation; selected: boolean; onClick: () => void }) { const mediaPreview: Record<string, string> = { image: "Foto", audio: "Áudio", video: "Vídeo", document: "Documento", sticker: "Figurinha" }; const preview = conversation.last_message_text || mediaPreview[conversation.last_message_type || ""] || "Mensagem"; return <button className={cn("w-full border-b px-3 py-3 text-left transition-colors hover:bg-muted/60", selected && "bg-primary/5 shadow-[inset_3px_0_0_hsl(var(--primary))]")} onClick={onClick}><div className="flex items-start gap-3"><ConversationAvatar conversation={conversation} className="h-10 w-10 shrink-0" /><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className="truncate text-sm font-medium">{conversationName(conversation)}</p><span className="shrink-0 text-[11px] text-muted-foreground">{listDate(conversation.last_message_at)}</span></div><div className="mt-1 flex items-center gap-2"><ChannelBadge channel={conversation.channel} />{conversation.conversation_type === "group" ? <Badge variant="outline" className="h-5 px-1.5 text-[10px]">Grupo</Badge> : null}<span className="truncate text-xs text-muted-foreground">{preview}</span></div><div className="mt-2 flex items-center justify-between gap-2"><span className="truncate text-[11px] text-muted-foreground">{conversation.assigned_user_name || "Sem responsável"} · {conversation.handling_mode === "ai" ? "IA" : "Humano"}</span>{conversation.unread_count > 0 ? <Badge className="h-5 min-w-5 justify-center rounded-full px-1.5 text-[10px]">{conversation.unread_count}</Badge> : null}</div></div></div></button>; }
function MessageBubble({ message, previous }: { message: CommunicationMessage; previous?: CommunicationMessage }) { const outbound = message.direction === "outbound"; const statusIcon = message.delivery_status === "failed" ? <span className="text-destructive">!</span> : message.delivery_status === "read" ? <CheckCheck className="h-3 w-3 text-sky-500" /> : outbound ? <Check className="h-3 w-3" /> : null; return <div className={cn("flex", outbound ? "justify-end" : "justify-start")}><div className={cn("max-w-[78%] rounded-lg px-3 py-2 text-sm shadow-sm", outbound ? "rounded-br-sm bg-primary text-primary-foreground" : "rounded-bl-sm border bg-card")}><p className="whitespace-pre-wrap break-words">{message.body_text || "Mensagem não textual"}</p><div className={cn("mt-1 flex items-center justify-end gap-1 text-[10px]", outbound ? "text-primary-foreground/70" : "text-muted-foreground")}><span>{formatTime(message.created_at)}</span>{statusIcon}</div></div></div>; }
function formatBudget(value?: string | null) { const digits = String(value || "").replace(/\D/g, ""); return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(digits || 0) / 100); }
function GroupProfilePanel({ detail, participants, onRefresh, onShared }: { detail: ConversationDetail; participants: Array<{ name: string | null; phone?: string | null; profilePictureUrl?: string | null; role: string }>; onRefresh: () => Promise<void>; onShared: (type: "media" | "documents" | "links") => void }) { const [query, setQuery] = useState(""); const filtered = participants.filter((participant) => `${participant.name || ""} ${participant.phone || ""}`.toLowerCase().includes(query.toLowerCase())); return <div className="space-y-5 p-4"><div className="flex flex-col items-center text-center"><ConversationAvatar conversation={detail} className="mb-3 h-16 w-16" /><h3 className="font-semibold">{conversationName(detail)}</h3><ChannelBadge channel={detail.channel} /><p className="mt-2 text-sm text-muted-foreground">{detail.participant_count || 0} participantes</p><Button className="mt-3" variant="ghost" size="sm" onClick={() => void onRefresh()}><RefreshCw className="mr-2 h-4 w-4" />Atualizar informações</Button></div>{participants.length ? <section className="space-y-2 border-t pt-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold uppercase text-muted-foreground">Participantes</p><span className="text-xs text-muted-foreground">{participants.length}</span></div><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar participante" className="h-8" /><div className="max-h-64 space-y-2 overflow-y-auto">{filtered.map((participant, index) => <div key={`${participant.phone || participant.name || "participant"}-${index}`} className="flex items-center gap-2 text-sm"><Avatar className="h-8 w-8"><AvatarImage src={participant.profilePictureUrl || undefined} alt={participant.name || participant.phone || "Participante"} referrerPolicy="no-referrer" /><AvatarFallback>{initials(participant.name || participant.phone)}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><span className="block truncate">{participant.name || participant.phone || "Participante"}</span>{participant.name && participant.phone ? <span className="block text-xs text-muted-foreground">{participant.phone}</span> : null}</div>{participant.role !== "Participante" ? <Badge variant="secondary" className="text-[10px]">{participant.role}</Badge> : null}</div>)}</div></section> : null}<section className="space-y-2 border-t pt-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Mídias, links e documentos</p><button onClick={() => onShared("media")} className="flex w-full items-center gap-2 rounded-md p-2 text-sm hover:bg-muted"><Images className="h-4 w-4 text-primary" />Mídias</button><button onClick={() => onShared("links")} className="flex w-full items-center gap-2 rounded-md p-2 text-sm hover:bg-muted"><Link className="h-4 w-4 text-primary" />Links</button><button onClick={() => onShared("documents")} className="flex w-full items-center gap-2 rounded-md p-2 text-sm hover:bg-muted"><FileText className="h-4 w-4 text-primary" />Documentos</button></section></div>; }
function ProfilePanel({ detail, users, availableLabels, onAssign, onCopyPhone, onOpenLead, onBudget, onLabels, onShared }: { detail: ConversationDetail; users: UserOption[]; availableLabels: ConversationLabel[]; onAssign: (value: string) => void; onCopyPhone: () => void; onOpenLead: () => void; onBudget: (value: string | null) => Promise<void>; onLabels: (ids: number[]) => Promise<void>; onShared: (type: "media" | "documents" | "links") => void }) { const [editingBudget, setEditingBudget] = useState(false); const [budget, setBudget] = useState(detail.lead_budget || ""); const [saving, setSaving] = useState(false); useEffect(() => setBudget(detail.lead_budget || ""), [detail.lead_budget]); const labelIds = (detail.lead_labels || []).map((item) => Number(item.id)); const saveBudget = async () => { setSaving(true); try { await onBudget(budget || null); setEditingBudget(false); } finally { setSaving(false); } }; const toggleLabel = async (id: number) => onLabels(labelIds.includes(id) ? labelIds.filter((item) => item !== id) : [...labelIds, id]); return <div className="space-y-5 p-4"><div className="flex flex-col items-center text-center"><Avatar className="mb-3 h-16 w-16"><AvatarFallback className="text-lg">{initials(detail.lead_name || detail.lead_phone)}</AvatarFallback></Avatar><h3 className="font-semibold">{detail.lead_name || detail.lead_phone || "Contato sem nome"}</h3><ChannelBadge /><div className="mt-2 flex items-center gap-1 text-sm text-muted-foreground">{detail.lead_phone || "Sem telefone"}{detail.lead_phone ? <Button variant="ghost" size="icon" className="h-6 w-6" onClick={onCopyPhone}><Copy className="h-3.5 w-3.5" /></Button> : null}</div><Button className="mt-3 w-full" variant="outline" onClick={onOpenLead}>Ver lead completo</Button></div><section className="space-y-3 border-t pt-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Comercial</p><div className="flex items-center justify-between text-sm"><span className="text-muted-foreground">Status</span><Badge variant="outline">{detail.lead_status || "Sem status"}</Badge></div><div><div className="mb-1 flex items-center justify-between"><span className="text-xs text-muted-foreground">Valor do orçamento</span>{!editingBudget ? <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => setEditingBudget(true)}><Pencil className="h-3.5 w-3.5" /></Button> : null}</div>{editingBudget ? <div className="space-y-2"><Input value={budget} onChange={(event) => setBudget(formatBudget(event.target.value))} onKeyDown={(event) => { if (event.key === "Enter") void saveBudget(); if (event.key === "Escape") { setBudget(detail.lead_budget || ""); setEditingBudget(false); } }} autoFocus /><div className="flex justify-end gap-2"><Button size="sm" variant="ghost" onClick={() => setEditingBudget(false)}>Cancelar</Button><Button size="sm" onClick={() => void saveBudget()} disabled={saving}>{saving ? "Salvando..." : "Salvar"}</Button></div></div> : <p className="text-lg font-semibold text-primary">{formatBudget(detail.lead_budget)}</p>}</div><div><p className="mb-1.5 text-xs text-muted-foreground">Responsável pelo atendimento</p><Select value={detail.assigned_user_id ? String(detail.assigned_user_id) : "unassigned"} onValueChange={onAssign}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="unassigned">Sem responsável</SelectItem>{users.map((item) => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select></div><div><p className="mb-2 text-xs text-muted-foreground">Etiquetas</p><div className="mb-2 flex flex-wrap gap-1">{(detail.lead_labels || []).map((label) => <button key={label.id} onClick={() => void toggleLabel(label.id)} className="rounded px-2 py-1 text-xs text-black" style={{ backgroundColor: label.color }} title="Remover etiqueta">{label.name} ×</button>)}</div><Select onValueChange={(value) => void toggleLabel(Number(value))}><SelectTrigger><SelectValue placeholder="Adicionar etiqueta" /></SelectTrigger><SelectContent>{availableLabels.filter((label) => !labelIds.includes(label.id)).map((label) => <SelectItem key={label.id} value={String(label.id)}>{label.name}</SelectItem>)}</SelectContent></Select></div></section><section className="space-y-2 border-t pt-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Mídias, links e documentos</p><button onClick={() => onShared("media")} className="flex w-full items-center gap-2 rounded-md p-2 text-sm hover:bg-muted"><Images className="h-4 w-4 text-primary" />Mídias</button><button onClick={() => onShared("links")} className="flex w-full items-center gap-2 rounded-md p-2 text-sm hover:bg-muted"><Link className="h-4 w-4 text-primary" />Links</button><button onClick={() => onShared("documents")} className="flex w-full items-center gap-2 rounded-md p-2 text-sm hover:bg-muted"><FileText className="h-4 w-4 text-primary" />Documentos</button></section><section className="border-t pt-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Atendimento</p><div className="mt-2 flex items-center gap-2 text-sm">{detail.handling_mode === "ai" ? <Bot className="h-4 w-4 text-sky-500" /> : <UserRound className="h-4 w-4 text-primary" />}{modeLabel(detail.handling_mode)}</div></section></div>; }

function SharedContentDialog({ conversationId, type, items, onClose }: { conversationId: number; type: "media" | "documents" | "links"; items: SharedConversationItem[]; onClose: () => void }) {
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [mediaUrls, setMediaUrls] = useState<Record<number, string>>({});
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const mediaItems = type === "media" ? items : [];
  const closeViewer = useCallback(() => {
    setSelectedIndex(null);
    requestAnimationFrame(() => triggerRef.current?.focus());
  }, []);
  const openViewer = useCallback((index: number, trigger: HTMLButtonElement) => {
    triggerRef.current = trigger;
    setSelectedIndex(index);
  }, []);
  const rememberMediaUrl = useCallback((id: number, url: string) => {
    setMediaUrls((current) => current[id] === url ? current : { ...current, [id]: url });
  }, []);
  const moveViewer = useCallback((offset: number) => {
    setSelectedIndex((current) => current === null ? null : Math.min(mediaItems.length - 1, Math.max(0, current + offset)));
  }, [mediaItems.length]);

  useEffect(() => {
    if (selectedIndex === null) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") closeViewer();
      if (event.key === "ArrowLeft") moveViewer(-1);
      if (event.key === "ArrowRight") moveViewer(1);
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [closeViewer, moveViewer, selectedIndex]);

  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4" role="dialog" aria-modal="true"><div className="max-h-[80vh] w-full max-w-3xl overflow-y-auto rounded-md border bg-card p-4"><div className="mb-4 flex items-center justify-between"><h2 className="font-semibold">{type === "media" ? "Mídias" : type === "links" ? "Links" : "Documentos"}</h2><Button variant="ghost" size="icon" onClick={onClose} aria-label="Fechar conteúdo compartilhado"><X className="h-4 w-4" /></Button></div>{items.length === 0 ? <p className="py-10 text-center text-sm text-muted-foreground">Nenhum conteúdo encontrado.</p> : type === "media" ? <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">{items.map((item, index) => <SharedMediaItem key={item.id} conversationId={conversationId} item={item} onReady={rememberMediaUrl} onOpen={(trigger) => openViewer(index, trigger)} />)}</div> : <div className="space-y-2">{items.map((item) => type === "links" ? <a key={`${item.id}-${item.url}`} href={item.url} target="_blank" rel="noopener noreferrer" className="block rounded-md border p-3 hover:bg-muted"><strong className="text-sm">{item.domain}</strong><span className="block truncate text-xs text-primary">{item.url}</span><span className="line-clamp-1 text-xs text-muted-foreground">{item.excerpt}</span></a> : <SharedDocumentItem key={item.id} conversationId={conversationId} item={item} />)}</div>}</div>{selectedIndex !== null && mediaItems[selectedIndex] ? <SharedMediaViewer conversationId={conversationId} item={mediaItems[selectedIndex]} objectUrl={mediaUrls[mediaItems[selectedIndex].id]} index={selectedIndex} total={mediaItems.length} onClose={closeViewer} onPrevious={() => moveViewer(-1)} onNext={() => moveViewer(1)} /> : null}</div>;
}
function SharedMediaItem({ conversationId, item, onReady, onOpen }: { conversationId: number; item: SharedConversationItem; onReady: (id: number, url: string) => void; onOpen: (trigger: HTMLButtonElement) => void }) {
  const { objectUrl, failed } = useAuthenticatedMediaUrl(conversationMediaUrl(conversationId, item.id), true, item.media_mime_type);
  useEffect(() => { if (objectUrl) onReady(item.id, objectUrl); }, [item.id, objectUrl, onReady]);
  if (failed) return <div className="aspect-square rounded-md border p-3 text-xs text-muted-foreground">Mídia indisponível</div>;
  if (!objectUrl) return <Skeleton className="aspect-square w-full" />;
  return <button type="button" className="group relative aspect-square w-full overflow-hidden rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary" onClick={(event) => onOpen(event.currentTarget)} aria-label={`Ampliar ${item.media_filename || (item.message_type === "video" ? "vídeo" : "imagem")}`}><span className="absolute right-2 top-2 z-10 rounded-sm bg-black/70 p-1.5 text-white opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100"><Expand className="h-4 w-4" /></span>{item.message_type === "video" ? <video src={objectUrl} muted playsInline preload="metadata" className="h-full w-full object-cover" /> : <img src={objectUrl} loading="lazy" alt={item.media_filename || "Mídia"} className="h-full w-full object-cover" />}</button>;
}
function SharedMediaViewer({ conversationId, item, objectUrl: cachedUrl, index, total, onClose, onPrevious, onNext }: { conversationId: number; item: SharedConversationItem; objectUrl?: string; index: number; total: number; onClose: () => void; onPrevious: () => void; onNext: () => void }) {
  const { objectUrl, failed } = useAuthenticatedMediaUrl(conversationMediaUrl(conversationId, item.id), !cachedUrl, item.media_mime_type);
  const mediaUrl = cachedUrl || objectUrl;
  return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 p-4 sm:p-10" role="dialog" aria-modal="true" aria-label="Visualização ampliada de mídia" onClick={onClose}><div className="relative flex h-full w-full items-center justify-center" onClick={(event) => event.stopPropagation()}><Button type="button" variant="secondary" size="icon" className="absolute right-0 top-0 z-20" onClick={onClose} aria-label="Fechar visualização"><X className="h-5 w-5" /></Button><Button type="button" variant="secondary" size="icon" className="absolute left-0 top-1/2 z-20 -translate-y-1/2" onClick={onPrevious} disabled={index === 0} aria-label="Mídia anterior"><ArrowLeft className="h-5 w-5" /></Button>{failed ? <p className="text-sm text-white/70">Mídia indisponível.</p> : !mediaUrl ? <Skeleton className="h-64 w-full max-w-xl" /> : item.message_type === "video" ? <video key={mediaUrl} src={mediaUrl} controls autoPlay playsInline className="max-h-[calc(100vh-8rem)] max-w-[calc(100vw-8rem)] object-contain" /> : <img src={mediaUrl} alt={item.media_filename || "Mídia ampliada"} className="max-h-[calc(100vh-8rem)] max-w-[calc(100vw-8rem)] object-contain" />}<Button type="button" variant="secondary" size="icon" className="absolute right-0 top-1/2 z-20 -translate-y-1/2" onClick={onNext} disabled={index === total - 1} aria-label="Próxima mídia"><ArrowRight className="h-5 w-5" /></Button><span className="absolute bottom-0 left-1/2 -translate-x-1/2 rounded-sm bg-black/70 px-3 py-1.5 text-sm text-white" aria-live="polite">{index + 1} / {total}</span></div></div>;
}
function SharedDocumentItem({ conversationId, item }: { conversationId: number; item: SharedConversationItem }) { const { objectUrl } = useAuthenticatedMediaUrl(conversationMediaUrl(conversationId, item.id), true, item.media_mime_type); return <a href={objectUrl || undefined} download={item.media_filename || "documento"} className="flex items-center gap-3 rounded-md border p-3 hover:bg-muted"><FileText className="h-6 w-6 text-primary" /><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{item.media_filename || "Documento"}</strong><span className="text-xs text-muted-foreground">{item.media_mime_type || "Arquivo"}</span></span></a>; }
function ActivityPanel({ activities }: { activities: ConversationActivity[] }) { return <div className="space-y-4 p-4">{activities.length === 0 ? <EmptyState icon={Clock3} title="Nenhuma atividade registrada" /> : activities.map((activity) => <div key={activity.id} className="relative border-l-2 border-primary/20 pl-4"><span className="absolute -left-[5px] top-1 h-2 w-2 rounded-full bg-primary" /><p className="text-sm font-medium">{activity.title}</p><p className="mt-1 text-xs text-muted-foreground">{formatDate(activity.created_at)} · {activity.actor_name || "Sistema"}</p>{activity.description ? <p className="mt-1 text-xs text-muted-foreground">{activity.description}</p> : null}</div>)}</div>; }
